<script setup>
import PublishDelivery from "./PublishDelivery.vue";
import { useRouter } from "vue-router";
import AppSelect from "../../shared/components/AppSelect.vue";
import { formatDate } from "../../shared/i18n/index.js";
import { computed, ref, watch } from "vue";
import { appApi } from "../../shared/api/api.js";
import { useResource } from "../../shared/api/use-resource.js";
import PageHeader from "../../shared/components/PageHeader.vue";
import StatusBadge from "../../shared/components/StatusBadge.vue";
import FeedbackMessage from "../../shared/components/FeedbackMessage.vue";
import MarkdownContent from "../../shared/components/MarkdownContent.vue";
const props = defineProps({ projectId: { type: String, required: true }, deliveryId: { type: String, required: true } });
const emit = defineEmits(["back"]);
const endpoint = `/projects/${props.projectId}/deliveries/${props.deliveryId}`;
const { data, loading, saving, error, reload, save } = useResource(() => appApi(endpoint));
const router = useRouter(), resubmitting = ref(false);
const reviewers = useResource(() => appApi(`/projects/${props.projectId}/reviewers`));
const reviewerId = ref("");
const checked = ref([]), note = ref(""), transitionId = ref("");
const canReview = computed(() => data.value?.canReview && data.value?.permissions.includes("deliverable.review") && data.value.delivery.status === "pending" && data.value.issue?.release?.status !== "archived");
const transitions = computed(() => (data.value?.issue?.availableTransitions || []).filter(t => data.value.permissions.includes(t.permission)));
watch(canReview, allowed => { if (!allowed) { checked.value = []; note.value = ""; transitionId.value = ""; } });
function resubmitted(value) { resubmitting.value = false; void router.push({ name: "deliveries", query: { projectId: props.projectId, delivery: value.id } }); }
function reassign() { return save(`${endpoint}/assign`, { revision: data.value.delivery.revision, reviewerId: reviewerId.value }, () => { reviewerId.value = ""; void reload(); }); }
function begin() { return save(`${endpoint}/start`, { revision: data.value.delivery.revision }, () => { void reload(); }); }
function review(status) { if (!canReview.value) return; return save(`${endpoint}/review`, { revision: data.value.delivery.revision, status, checkedItems: checked.value, reviewNote: note.value, ...(transitionId.value ? { transitionId: transitionId.value, issueRevision: data.value.issue.revision } : {}) }, () => { void reload(); }, status === "accepted" ? "交付已通过验收。" : "已退回交付，并记录原因。"); }
</script>
<template><button class="ui-back" @click="emit('back')">{{ $t("← 返回交付") }}</button><FeedbackMessage :message="error" type="error" /><button v-if="error" @click="reload">{{ $t("重新读取") }}</button><p v-if="loading && !data" role="status">{{ $t("正在读取交付…") }}</p><template v-if="data"><PageHeader :title="data.delivery.title" :description="$t('审阅成果，逐项核对，再记录验收结论。')"><StatusBadge :tone="data.delivery.status === 'accepted' ? 'success' : 'neutral'">{{ { pending: $t("待验证"), accepted: $t("已通过"), returned: $t("已退回") }[data.delivery.status] }}</StatusBadge></PageHeader><div class="ui-detail-columns"><div><section class="ui-content-section"><h2>{{ $t("交付说明") }}</h2><MarkdownContent :content="data.delivery.body" /></section><section class="ui-content-section"><p v-if="data.delivery.status === 'pending'">{{ $t("验证进度") }}：{{ $t(data.delivery.verificationStartedAt ? "验证中" : "待开始验证") }}</p><button v-if="canReview && !data.delivery.verificationStartedAt" :disabled="saving" @click="begin">{{ $t("开始验证") }}</button><h2>{{ $t("验收核对") }}</h2><label v-for="(item, index) in data.delivery.checklist" :key="index" class="ui-check-row"><input v-if="canReview" v-model="checked" type="checkbox" :value="index" :disabled="saving" /><input v-else type="checkbox" :checked="data.delivery.checkedItems.includes(index)" disabled /><span>{{ item }}</span></label></section><form v-if="canReview" class="project-form ui-content-section" @submit.prevent="review('accepted')"><label>{{ $t("验收说明") }}<textarea v-model="note" rows="4" maxlength="4000" :disabled="saving" :placeholder="$t('记录验证结果；退回时请说明原因。')" /></label><label v-if="data.issue">{{ $t("同时更新事项状态") }}<AppSelect native-events v-model="transitionId" :disabled="saving"><option value="">{{ $t("保持当前状态") }}</option><option v-for="t in transitions" :key="t.id" :value="t.id">{{ t.name }}</option></AppSelect></label><p v-if="data.issue" class="field-hint">{{ $t("交付验收与事项流程分别记录；如需流转，可选择当前允许的操作。") }}</p><div class="actions"><button type="submit" class="primary" :disabled="saving || checked.length !== data.delivery.checklist.length">{{ $t("通过验收") }}</button><button type="button" :disabled="saving || !note.trim()" @click="review('returned')">{{ $t("退回修改") }}</button></div></form><section v-else-if="data.delivery.reviewedAt" class="ui-content-section"><h2>{{ $t("验收记录") }}</h2><p>{{ data.people.find(p => p.id === data.delivery.reviewedById)?.displayName }} · {{ formatDate(data.delivery.reviewedAt, { hour: "2-digit", minute: "2-digit" }) }}</p><p class="project-text">{{ data.delivery.reviewNote || $t("全部核对项已确认。") }}</p></section></div><aside class="ui-detail-aside"><template v-if="data.issue"><h2>{{ $t("关联事项") }}</h2><RouterLink :to="{ name: 'project', params: { projectId }, query: { tab: data.issue.type === 'bug' ? 'bugs' : 'issues', issue: data.issue.id } }">#{{ data.issue.number }} {{ data.issue.title }}</RouterLink><p class="muted">{{ data.issue.statusName }}</p></template><p v-else>{{ $t("独立开发交付") }}</p><h3>{{ $t("提交标识") }}</h3><code>{{ data.delivery.commit || $t("未提供") }}</code><h3>{{ $t("交付验证人") }}</h3><p>{{ data.people.find(p => p.id === data.delivery.reviewerId)?.displayName || $t("历史成员") }}</p><RouterLink v-if="data.delivery.supersededById" :to="{ name: 'deliveries', query: { projectId, delivery: data.delivery.supersededById } }">{{ $t("查看重新提交的交付") }}</RouterLink><RouterLink v-if="data.delivery.supersedesId" :to="{ name: 'deliveries', query: { projectId, delivery: data.delivery.supersedesId } }">{{ $t("查看原交付") }}</RouterLink><button v-if="data.canResubmit && data.permissions.includes('deliverable.create') && data.issue?.release?.status !== 'archived'" @click="resubmitting = true">{{ $t("修改并重新提交") }}</button><form v-if="data.delivery.status === 'pending' && data.permissions.includes('issue.assign') && data.issue?.release?.status !== 'archived'" class="project-form" @submit.prevent="reassign"><FeedbackMessage :message="reviewers.error.value" type="error" /><label>{{ $t("重新指定验证人") }}<AppSelect native-events v-model="reviewerId" :aria-label="$t('重新指定验证人')" :disabled="saving || reviewers.loading.value"><option value="">{{ $t("选择明确的验证人") }}</option><option v-for="person in reviewers.data.value?.items || []" :key="person.id" :value="person.id">{{ person.displayName }}</option></AppSelect></label><button :disabled="saving || !reviewerId">{{ $t("确认分派") }}</button></form><h3>{{ $t("发布人") }}</h3><p>{{ data.people.find(p => p.id === data.delivery.authorId)?.displayName || $t("历史成员") }}</p></aside></div><PublishDelivery v-if="resubmitting" :project-id="projectId" :previous="data.delivery" @close="resubmitting = false" @published="resubmitted" /></template></template>
